#include <math.h>

#include "crimsonland_gameplay.h"

static __inline float abs_bits(float value)
{
    unsigned int bits = *(unsigned int *)&value;
    bits &= 0x7fffffff;
    return *(float *)&bits;
}

float abs_vel_x =
    abs_bits(secondary->pos.vx.vel_x);
float abs_vel_y =
    abs_bits(secondary->pos.vx.vy.vel_y);
secondary->pos.vx.vy.trail_timer -=
    (abs_vel_x + abs_vel_y) * frame_dt * 0.01f;

float abs_vel_x = secondary->pos.vx.vel_x;
float abs_vel_y = secondary->pos.vx.vy.vel_y;
*(unsigned int *)&abs_vel_x &= 0x7fffffff;
*(unsigned int *)&abs_vel_y &= 0x7fffffff;
secondary->pos.vx.vy.trail_timer -=
    (abs_vel_x + abs_vel_y) * frame_dt * 0.01f;

unsigned int abs_vel_x =
    *(unsigned int *)&secondary->pos.vx.vel_x;
unsigned int abs_vel_y =
    *(unsigned int *)&secondary->pos.vx.vy.vel_y;
abs_vel_x &= 0x7fffffff;
abs_vel_y &= 0x7fffffff;
secondary->pos.vx.vy.trail_timer -=
    (*(float *)&abs_vel_x + *(float *)&abs_vel_y)
    * frame_dt * 0.01f;

unsigned int abs_vel_x_bits =
