unsigned int abs_vel_y_bits =
    *(unsigned int *)&secondary->pos.vx.vy.vel_y;
abs_vel_x_bits &= 0x7fffffff;
abs_vel_y_bits &= 0x7fffffff;
float abs_vel_x = *(float *)&abs_vel_x_bits;
float abs_vel_y = *(float *)&abs_vel_y_bits;
secondary->pos.vx.vy.trail_timer -=
    (abs_vel_x + abs_vel_y) * frame_dt * 0.01f;

